-- photo-1-estate.commit.sql
--
-- ============================== COMMIT - THIS WRITES ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. The preflight is optional: this file verifies everything inside
-- its transaction and keeps nothing when a check fails.
--
-- WHAT THIS DOES, in one transaction on the estate database:
--   1. retains, through model.mint_content_artifact, the bytes of the canonical feature of nerdery-view-collected-animal
--      (sha256:d01b38d276d161ba76402d4f3fbd10cd88a98f4c40c9f07e00f7f068b5874e45) and the promise flight-promise:nerdery-collected-animal-photo-view;
--   2. compiles the capability's DSL with the installed compiler against those bytes: COMPILED to sha256:e6f62d7eb71418ca3a2cd7d5963af711b78feb2a7b529aee316e33844b68e796,
--      the document the flight declares;
--   3. publishes two pages through sidefx_ui.stage_ui_page and sidefx_ui.promote_ui_page: wildlife-mine revision 2, whose
--      cards each open their individual, and wildlife-individual revision 1, which shows the individual's photo. Both read
--      back READ through analysis.read_ui_page_document.
-- WHERE: the estate database. Run the whole file in one session (under a minute).
-- BASES: compiler body sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81, mint sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e, the no-drift check installed, wildlife-mine current at
-- revision 1 with its reviewed digest, no wildlife-individual page yet.
-- RESULT SETS: base; minted (2 rows); readback (retained 1 each); compile (status COMPILED, document = expected); pages
-- (2 rows, digest_matches 1, read_status READ).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @cd nvarchar(max)=REPLACE(OBJECT_DEFINITION(OBJECT_ID(N'analysis.compile_capability_dsl')),NCHAR(13)+NCHAR(10),NCHAR(10));
SET @cd=SUBSTRING(@cd,CHARINDEX(N'PROCEDURE analysis.compile_capability_dsl',@cd),DATALENGTH(@cd)/2);
WHILE DATALENGTH(@cd)>0 AND RIGHT(@cd,1) IN (NCHAR(10),NCHAR(13),NCHAR(32),NCHAR(9)) SET @cd=LEFT(@cd,DATALENGTH(@cd)/2-1);
DECLARE @cd_digest varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),@cd COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @m varchar(80)='sha256:'+LOWER(CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varchar(max),OBJECT_DEFINITION(OBJECT_ID(N'model.mint_content_artifact')) COLLATE Latin1_General_100_BIN2_UTF8)),2));
DECLARE @check int=CASE WHEN OBJECT_ID(N'analysis.check_capability_feature_conformance') IS NOT NULL THEN 1 ELSE 0 END;
DECLARE @mine_revision int=(SELECT revision FROM sidefx_ui.ui_current_page WHERE page_id=N'ui-page-wildlife-mine');
DECLARE @mine_digest char(64)=(SELECT d.digest FROM sidefx_ui.ui_current_page c JOIN sidefx_ui.ui_page_definition d ON d.page_id=c.page_id AND d.revision=c.revision WHERE c.page_id=N'ui-page-wildlife-mine');
DECLARE @individual int=(SELECT COUNT(*) FROM sidefx_ui.ui_page_definition WHERE page_id=N'ui-page-wildlife-individual' OR path=N'/circuit/wildlife-individual');
DECLARE @layout int=(SELECT COUNT(*) FROM sidefx_ui.ui_layout_definition WHERE layout_id=N'ui-layout-marketing.v1' AND digest='e2591ca34ce894541132dccaca54fa77d8e98b84e7f8c8c8c93ff320fe9db58c');
SELECT N'base' AS result_set,@cd_digest AS compiler_body,'sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81' AS compiler_expected,@m AS mint_installed,@check AS check_installed,
 @mine_revision AS mine_revision,@mine_digest AS mine_digest,@individual AS individual_pages,@layout AS layout_declared;
IF @cd_digest IS NULL OR @cd_digest<>'sha256:a437984d1e7691557b473adb9b1650467ecb67a40e9a6b1251f4f7c01d3a9a81' OR @m IS NULL OR @m<>'sha256:d6f8025a8c5e0d891a50d11df06dc0f2a1785eb7bdd977d0cd45e89eaca2516e' OR @check<>1 OR ISNULL(@mine_revision,0)<>1
 OR ISNULL(@mine_digest,'')<>'4610946505f48000ca9a781114f66993f1552b7dc4535e3e36978310ddb5919b' OR @individual<>0 OR @layout<>1
BEGIN
 RAISERROR(N'PHOTO1_BASE: the compiler, the mint, the check, wildlife-mine or the layout is not the reviewed base, or wildlife-individual exists already; nothing is changed.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
SET NOCOUNT ON;
DECLARE @minted TABLE(ordinal int IDENTITY(1,1),value nvarchar(max));
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"capability-feature:nerdery-view-collected-animal","text":"# nerdery-view-collected-animal: canonical feature for the SideFX build, 2026-11-03.\n# Product authority: source/nerdery-architecture-design-challenge.pdf, identified in source/source-manifest.json.\n# Authoring convention: the two supplied canonical feature examples, as the citizen slice''s features follow them; not a new\n# platform format.\n# Status: written for the owner''s request to see the photo of a collected animal when looking back at their animals. The\n# owner-review package nerdery-canonical-features has no feature that reads a stored photo back; this one is canonical for\n# the build and lives beside the slice''s finalized features. Its arrangements are nerdery/fixtures/cases/*.json over that\n# package''s pinned base state.\n# @status:probed: the case ran read-only against the wildlife procedures through nerdery/conformance/run-cases.mjs\n# (run ef3510aa).\n# Every Scenario below is an acceptance case of the ONE circuit scenario tagged on this Feature.\n# Given / When / Then are exact across cases. Given holds the request JSON. Then holds operation/path/equals.\n# Values: true/false/null/numbers/arrays/objects are JSON values; other values are strings; (absent) selects nothing.\n# Authentication, fixture state and dependency behavior come from the pinned test arrangement, never caller role claims.\n# Provider: the operation is one sql-database-reader statement on sfx-identity (EXEC wildlife.serve), so every case is\n# tagged @provider:sql-database-reader.\n# The JSON under Given is the request body. The declared API operation binds the caller from the session the frontdoor\n# validated; the capability input is {caller, request}. Fixture preparation is separate.\n# A read changes nothing: every case leaves the stored state as it was.\n# All JSON shapes/identities are proposed under D01. Case design decisions remain proposals, not Nerdery requirements.\n# Scope: mvp. Source requirements: NRD-E06, NRD-E07.\n# Proposed outcome contract: nerdery-view-collected-animal-result.v1; terminal variants: VISIBLE, REFUSED.\n# Proposed operation identity: nerdery-view-collected-animal.view.\n\n@capability:nerdery-view-collected-animal\n@root-scenario:nerdery-view-collected-animal\n@scenario:nerdery-view-collected-animal\n@input:nerdery-view-collected-animal-request\n@input-contract:nerdery-view-collected-animal-request.v1\n@event:nerdery-view-collected-animal-requested\n@event-authority:nerdery-view-collected-animal.v1\n@outcome:nerdery-view-collected-animal-outcome\n@outcome-contract:nerdery-view-collected-animal-result.v1\n@outcome-terminal\nFeature: View one collected individual with its photo\n  As a citizen or biologist\n  I want to open an animal in my collection and see the photo I uploaded for it\n  So that I see my own photo of the animal together with what I recorded about it\n\n  Rule: An individual is shown with the user''s stored photo, nickname and recorded location\n\n    # Source requirements: NRD-E06, NRD-E07.\n    # Proposed decisions: D01, D05, D10.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-visible.json (sha256:aa1802d1cc3578179f6be1220fff5c3cfdc0469a8fddfb29c9f482a3154e71ee).\n    # The photo is returned as its stored bytes, base64 encoded, with the media type and digest recorded at upload.\n    @case:nrd-individual-visible\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: The owner views a recorded individual with the photo they uploaded\n      Given a request to view one collected individual\n        \"\"\"json\n        {\n          \"encounterId\": \"enc-001\"\n        }\n        \"\"\"\n      And Avery recorded enc-001, a Demo Heron nicknamed Reed, with the photo photo-a\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | VISIBLE |\n        | nerdery-view-collected-animal.view | $.animal.encounterId | enc-001 |\n        | nerdery-view-collected-animal.view | $.animal.ownerUserId | user-a |\n        | nerdery-view-collected-animal.view | $.animal.definitionId | animal-001 |\n        | nerdery-view-collected-animal.view | $.animal.commonName | Demo Heron |\n        | nerdery-view-collected-animal.view | $.animal.nickname | Reed |\n        | nerdery-view-collected-animal.view | $.animal.displayName | Reed |\n        | nerdery-view-collected-animal.view | $.animal.location | {\"source\":\"manual\",\"description\":\"Synthetic park, north path\"} |\n        | nerdery-view-collected-animal.view | $.animal.photo.photoRef | photo-a |\n        | nerdery-view-collected-animal.view | $.animal.photo.mediaType | image/png |\n        | nerdery-view-collected-animal.view | $.animal.photo.byteLength | 73 |\n        | nerdery-view-collected-animal.view | $.animal.photo.contentSha256 | sha256:8021bd6b739aa5464382e945cf4ab848c30f467b91ddb40d1c350354ec21cfa6 |\n        | nerdery-view-collected-animal.view | $.animal.photo.contentBase64 | iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEElEQVR4nGOInpwLRAwQCgAlugVtTkdgTAAAAABJRU5ErkJggg== |\n\n    # Source requirements: NRD-E07.\n    # Proposed decisions: D01, D05.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-fallback-name.json (sha256:ebfe17577898d48674d88b026fb9a219ccf99315e07fa4e6eca029fc9f5cf0a1).\n    @case:nrd-individual-fallback-name\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Without a nickname the common name labels the user''s photo\n      Given a request to view one collected individual\n        \"\"\"json\n        {\n          \"encounterId\": \"enc-003\"\n        }\n        \"\"\"\n      And Avery recorded enc-003, a Demo Fox without a nickname, with the photo photo-a\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | VISIBLE |\n        | nerdery-view-collected-animal.view | $.animal.encounterId | enc-003 |\n        | nerdery-view-collected-animal.view | $.animal.commonName | Demo Fox |\n        | nerdery-view-collected-animal.view | $.animal.nickname | null |\n        | nerdery-view-collected-animal.view | $.animal.displayName | Demo Fox |\n        | nerdery-view-collected-animal.view | $.animal.photo.photoRef | photo-a |\n        | nerdery-view-collected-animal.view | $.animal.photo.contentSha256 | sha256:8021bd6b739aa5464382e945cf4ab848c30f467b91ddb40d1c350354ec21cfa6 |\n\n  Rule: Only the authenticated owner can view an individual and its photo\n\n    # Source requirements: NRD-E06.\n    # Proposed decisions: D01, D05.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-other-owner.json (sha256:a1cca5284f3916276b543959aed4c4ebc1fa6589ebf7a5c47c7fe6b88bc6617f).\n    # Another user''s individual is answered as not found, so its existence is not revealed.\n    @case:nrd-individual-other-owner\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Another user''s individual cannot be viewed\n      Given a request to view one collected individual\n        \"\"\"json\n        {\n          \"encounterId\": \"enc-008\"\n        }\n        \"\"\"\n      And enc-008 belongs to Blake and Avery is the authenticated user\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | REFUSED |\n        | nerdery-view-collected-animal.view | $.reason.code | ENCOUNTER_NOT_FOUND |\n        | nerdery-view-collected-animal.view | $.animal | (absent) |\n\n    # Source requirements: NRD-E06.\n    # Proposed decisions: D01, D05.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-not-found.json (sha256:b69f7091c2350134267bac91695eaca4da3522a615b27cce0578adc34fda3ee3).\n    @case:nrd-individual-not-found\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An encounter that was never recorded cannot be viewed\n      Given a request to view one collected individual\n        \"\"\"json\n        {\n          \"encounterId\": \"enc-404\"\n        }\n        \"\"\"\n      And no encounter enc-404 is recorded for any user\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | REFUSED |\n        | nerdery-view-collected-animal.view | $.reason.code | ENCOUNTER_NOT_FOUND |\n        | nerdery-view-collected-animal.view | $.animal | (absent) |\n\n    # Source requirements: NRD-E06.\n    # Proposed decisions: D01.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-selection-required.json (sha256:a561cf5561ae2b1863384e5eb1ee3f4d6b148c4430bc7b30522d86c3e446042f).\n    @case:nrd-individual-selection-required\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: Viewing an individual requires naming its encounter\n      Given a request to view one collected individual\n        \"\"\"json\n        {}\n        \"\"\"\n      And Avery is signed in and the request names no encounter\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | REFUSED |\n        | nerdery-view-collected-animal.view | $.reason.code | ENCOUNTER_SELECTION_REQUIRED |\n        | nerdery-view-collected-animal.view | $.animal | (absent) |\n\n    # Source requirements: NRD-E06.\n    # Proposed decisions: D01, D05.\n    # Arrangement: nerdery/fixtures/cases/nrd-individual-anonymous.json (sha256:fe986dd73412613829810adabc6fccf81152cb3778f706f501867d0d0e189028).\n    # Refused inside the operation''s one provider call; the stored state is unchanged.\n    @case:nrd-individual-anonymous\n    @status:probed\n    @provider:sql-database-reader\n    Scenario: An unauthenticated request cannot view an individual\n      Given a request to view one collected individual\n        \"\"\"json\n        {\n          \"encounterId\": \"enc-001\"\n        }\n        \"\"\"\n      And no authenticated subject is available for the personal collection\n      When the individual and its stored photo are read for the authenticated user\n      Then the user can view the individual with its photo or a named refusal\n        | operation | path | equals |\n        | nerdery-view-collected-animal.view | $.status | REFUSED |\n        | nerdery-view-collected-animal.view | $.reason.code | AUTHENTICATION_REQUIRED |\n        | nerdery-view-collected-animal.view | $.animal | (absent) |\n"}';
INSERT @minted(value) EXEC model.mint_content_artifact @document=N'{"artifactKind":"flight-promise:nerdery-collected-animal-photo-view","text":"{\"contractId\":\"flight-promise.v1\",\"promiseId\":\"nerdery-collected-animal-photo-view\",\"workClass\":\"owner-objective\",\"statement\":\"OV3 declares nerdery-view-collected-animal, the view of one collected individual with the photo its owner uploaded, feature first: the declaration binds the retained bytes of its canonical feature and commits only when the check finds the binding CONFORMANT, and the stored document is exactly the reviewed one.\",\"obligations\":[{\"obligationId\":\"O1\",\"statement\":\"nerdery-view-collected-animal is declared from nerdery/dsl/nerdery-view-collected-animal.dsl, pinned to its canonical feature sha256:d01b38d276d161ba76402d4f3fbd10cd88a98f4c40c9f07e00f7f068b5874e45, and its stored document is sha256:e6f62d7eb71418ca3a2cd7d5963af711b78feb2a7b529aee316e33844b68e796.\",\"evidence\":\"apply-declared-change COMMITTED; read-declared-capability-document $.documentDigest sha256:e6f62d7eb71418ca3a2cd7d5963af711b78feb2a7b529aee316e33844b68e796\"}]}"}';
SELECT N'minted' AS result_set,ordinal,JSON_VALUE(value,'$.artifact_kind') AS artifact_kind,JSON_VALUE(value,'$.action') AS action,JSON_VALUE(value,'$.content_digest') AS content_digest FROM @minted ORDER BY ordinal;
DECLARE @want TABLE(ordinal int PRIMARY KEY,artifact_kind nvarchar(80),digest varchar(80));
INSERT @want VALUES(1,N'capability-feature:nerdery-view-collected-animal','sha256:d01b38d276d161ba76402d4f3fbd10cd88a98f4c40c9f07e00f7f068b5874e45'),(2,N'flight-promise:nerdery-collected-animal-photo-view','sha256:9be1101538a9b75fe4ea7dcd9d7ab7eb3d45001647e14154cf1ae69d161e6e61');
SELECT N'readback' AS result_set,w.ordinal,w.artifact_kind,w.digest,CASE WHEN EXISTS(SELECT 1 FROM model.content_artifact a WHERE a.artifact_kind=w.artifact_kind COLLATE Latin1_General_100_BIN2 AND a.content_digest=CONVERT(binary(32),SUBSTRING(w.digest,8,64),2)) THEN 1 ELSE 0 END AS retained FROM @want w ORDER BY w.ordinal;
IF EXISTS(SELECT 1 FROM @want w WHERE NOT EXISTS(SELECT 1 FROM model.content_artifact a WHERE a.artifact_kind=w.artifact_kind COLLATE Latin1_General_100_BIN2 AND a.content_digest=CONVERT(binary(32),SUBSTRING(w.digest,8,64),2)))
BEGIN
 RAISERROR(N'PHOTO1_VERIFY_FAILED: a retained text is not under the digest of its reviewed bytes; nothing is kept.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
DECLARE @e bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @in nvarchar(max),@r nvarchar(max);
DECLARE @t TABLE(v nvarchar(max));
SET @in=(SELECT N'capability nerdery-view-collected-animal
feature nerdery-view-collected-animal sha256:d01b38d276d161ba76402d4f3fbd10cd88a98f4c40c9f07e00f7f068b5874e45
intent: View one collected individual with its photo, for the caller whose session the declared API operation verified (Nerdery wildlife application, citizen slice)
outcome: nerdery-view-collected-animal-result.v1 VISIBLE or REFUSED, each refusal named by its reason code, so that I see my own photo of the animal together with what I recorded about it
input contract nerdery-view-collected-animal-request.v1 {"type":"object","additionalProperties":false,"required":["request"],"properties":{"caller":{"type":"object","additionalProperties":false,"properties":{"principalId":{"type":"string"},"sessionId":{"type":"string"}}},"request":{"type":"object"}}}
output contract nerdery-view-collected-animal-result.v1 {"type":"object","additionalProperties":true,"required":["contractId","status"],"properties":{"contractId":{"const":"nerdery-view-collected-animal-result.v1"},"status":{"enum":["VISIBLE","REFUSED"]}}}
cli display outcome as json
scenario nerdery-view-collected-animal root terminal
given: a request to view one collected individual
when: the individual and its stored photo are read for the authenticated user
then: the user can view the individual with its photo or a named refusal
operation nerdery-view-collected-animal.view uses provider sql-database-reader
config: {"dataSource":"sfx-identity-database","statement":"EXEC wildlife.serve @operation=N''nerdery-view-collected-animal'',@input=@input;","resultColumn":"value"}
input input from nerdery-view-collected-animal $
outcome from nerdery-view-collected-animal.view $.value
' AS source FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
INSERT @t(v) EXEC analysis.compile_capability_dsl @input=@in,@estate_model_pk=@e;
SELECT @r=v FROM @t;
SELECT N'compile' AS result_set,JSON_VALUE(@r,N'$.status') AS status,JSON_VALUE(@r,N'$.documentDigest') AS document,'sha256:e6f62d7eb71418ca3a2cd7d5963af711b78feb2a7b529aee316e33844b68e796' AS expected;
IF ISNULL(JSON_VALUE(@r,N'$.status'),N'')<>N'COMPILED' OR ISNULL(JSON_VALUE(@r,N'$.documentDigest'),N'')<>N'sha256:e6f62d7eb71418ca3a2cd7d5963af711b78feb2a7b529aee316e33844b68e796'
BEGIN
 RAISERROR(N'PHOTO1_COMPILE_FAILED: the DSL does not compile to the reviewed document against the retained feature; nothing is kept.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
DECLARE @pages TABLE(ordinal int PRIMARY KEY,page_id nvarchar(400) COLLATE Latin1_General_100_BIN2,path nvarchar(400) COLLATE Latin1_General_100_BIN2,
 revision int,expected_current int,document nvarchar(max),digest char(64) COLLATE Latin1_General_100_BIN2);
